# Deduplicate and build final registry
registry_map = {}

# Keep existing first
for c in existing:
    key = f"{c['ats']}::{c['slug'].lower()}"
    registry_map[key] = {
        "company": c["company"],
        "ats": c["ats"],
        "slug": c["slug"],
        "domain": c.get("domain", ""),
        "hub": c.get("hub") or c.get("default_hub", "Remote / India"),
    }

# Add Remote Companies
for c in NEW_REMOTE_COMPANIES + GLOBAL_REMOTE_TIER_B + NEW_REMOTE_COMPANIES_TIER_C:
    key = f"{c['ats']}::{c['slug'].lower()}"
    if key not in registry_map:
        registry_map[key] = {
            "company": c["company"],
            "ats": c["ats"],
            "slug": c["slug"],
            "domain": c.get("domain", ""),
            "hub": c.get("hub") or c.get("default_hub", "Remote / Global"),
        }

# Add India Companies
for c in NEW_INDIA_COMPANIES:
    key = f"{c['ats']}::{c['slug'].lower()}"
    if key not in registry_map:
        registry_map[key] = {
            "company": c["company"],
            "ats": c["ats"],
            "slug": c["slug"],
            "domain": c.get("domain", ""),
            "hub": c.get("hub") or c.get("default_hub", "Bengaluru / Remote India"),
        }

final_registry = list(registry_map.values())
# Sort alphabetically
final_registry.sort(key=lambda x: x["company"].lower())

remote_count = sum(1 for c in final_registry if "remote" in c["hub"].lower() or "global" in c["hub"].lower() or "worldwide" in c["hub"].lower())
india_count = sum(1 for c in final_registry if any(k in c["hub"].lower() for k in ["india", "bengaluru", "pune", "mumbai", "delhi", "gurgaon", "noida", "hyderabad", "chennai"]))

print(f"Total Unique Companies in Expanded Registry: {len(final_registry)}")
print(f"Total Worldwide Remote Companies: {remote_count} (Requirement >= 500)")
print(f"Total Companies Hiring in India: {india_count} (Requirement >= 100)")

assert remote_count >= 500, f"Remote count {remote_count} is less than required 500!"
assert india_count >= 100, f"India count {india_count} is less than required 100!"

with open(REGISTRY_PATH, "w", encoding="utf-8") as f:
    json.dump(final_registry, f, indent=2, ensure_ascii=False)

print(f"Successfully saved {len(final_registry)} companies to {REGISTRY_PATH}")
